import{_ as t,o as d,c,a2 as r}from"./chunks/framework.BZO4qERu.js";const l=JSON.parse('{"title":"研究工作区维护指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/developers/architecture.md","filePath":"zh/developers/architecture.md","lastUpdated":1792570296000}'),o={name:"zh/developers/architecture.md"};function s(p,e,a,i,n,b){return d(),c("div",null,[...e[0]||(e[0]=[r('<h1 id="研究工作区维护指南" tabindex="-1">研究工作区维护指南 <a class="header-anchor" href="#研究工作区维护指南" aria-label="Permalink to &quot;研究工作区维护指南&quot;">​</a></h1><p>社区版是共享 Python 与 Vue 实现的来源。在线版基于相同源码构建，部署适配层不应复制算法或页面。</p><p>共享 UI 变量、布局规则和样式归属见<a href="./design-system">界面规范</a>。下表中 Python 路径相对于 <code>backend/src/</code>，Web 路径相对于仓库根目录。</p><table tabindex="0"><thead><tr><th>职责</th><th>位置</th></tr></thead><tbody><tr><td>精简原生元数据与文献身份</td><td><code>paperseek_core/bibliometrics/corpus.py</code></td></tr><tr><td>分布与覆盖率</td><td><code>paperseek_core/bibliometrics/statistics.py</code></td></tr><tr><td>有界稀疏网络</td><td><code>paperseek_core/bibliometrics/networks.py</code></td></tr><tr><td>分析的创建、读取、导出与删除</td><td><code>paperseek_app/bibliometrics/services.py</code></td></tr><tr><td>存储契约与轻量记录模型</td><td><code>paperseek_app/bibliometrics/ports.py</code>、<code>models.py</code></td></tr><tr><td>社区版持久化与 HTTP 组合</td><td><code>paperseek_community/persistence/sqlite_bibliometrics.py</code>、<code>api_routes/bibliometrics.py</code></td></tr><tr><td>导航、菜单与模块历史</td><td><code>web/src/features/workspace/</code></td></tr><tr><td>分析视图、控件与浏览器布局 worker</td><td><code>web/src/features/bibliometrics/</code></td></tr><tr><td>检索草稿与模型连接输入</td><td><code>web/src/features/search/search-draft.ts</code>、<code>web/src/features/search/use-search-configuration.ts</code>、<code>web/src/features/settings/ConnectionSheet.vue</code></td></tr><tr><td>综述证据与来源图谱快照</td><td><code>web/src/features/review/ReviewEvidence.vue</code></td></tr><tr><td>共享设置契约与校验</td><td><code>paperseek_app/settings.py</code></td></tr><tr><td>部署无关的连接检测</td><td><code>paperseek_app/settings_probes.py</code>（客户端与来源由部署层提供）</td></tr><tr><td>综述结构化输出与修复</td><td><code>paperseek_core/review/structured.py</code></td></tr><tr><td>综述证据提取与大纲</td><td><code>paperseek_core/review/planning.py</code></td></tr><tr><td>综述正文生成与核对</td><td><code>paperseek_core/review/generation.py</code>；共享提示词在 <code>prompts.py</code></td></tr></tbody></table><p>检索在通道选择与融合前保留已返回页面的元数据，排序输入仍受原有上限约束。完成的任务独立写入 <code>bibliometric_corpus</code> 产物；结果 API 与事件流不传输候选集。社区版恢复检查点保留候选集；在线版可按策略跳过检查点，但仍保留最终产物。</p><p>创建分析时，将精简候选集和概览复制到独立压缩文件。SQL 保存摘要、描述信息和有界网络缓存引用。详情请求只读概览，网络计算与候选集导出按需加载候选集。删除流程先标记记录，再删除文件，最后保留最小幂等墓碑，避免迟到的重试重新创建记录。适配层在向用例暴露文件描述信息前检查所有权。</p><p>核心层明确限制网络规模，API 限制并发昂贵操作，浏览器 worker 只负责布局。精简候选集不重复保存大型源载荷、摘要、完整结果或模型凭据。不要将重型分析移入历史列表或页面挂载过程。</p><p>检索与综述的显示标题独立于问题、主题及执行版本。各模块历史共用 UI 行为，API 各自负责持久化。未保存的密钥输入位于表单内存；已保存连接与来源密钥由 <code>paperseek_community/workspace_settings.py</code> 加密，<code>web/src/features/settings/store.ts</code> 只缓存公开元数据。提交任务时另存加密凭据副本。账户切换时需重置草稿及按用户隔离的设置与历史。恢复历史任务不得静默改用当前服务默认值。</p><p>相关变更后，运行 <code>test_bibliometrics.py</code>、检索边界与恢复契约、导入边界检查、前端类型检查，以及 <code>web/tests/browser/</code> 下的 <code>shell.spec.ts</code>、<code>settings.spec.ts</code>、<code>records.spec.ts</code>、<code>reviews.spec.ts</code>。可选脚本 <code>backend/scripts/benchmark_bibliometrics.py</code> 记录 3,000／10,000 篇合成文献的开销，不代表远程服务或浏览器延迟。</p><h2 id="工作区界面" tabindex="-1">工作区界面 <a class="header-anchor" href="#工作区界面" aria-label="Permalink to &quot;工作区界面&quot;">​</a></h2><p><code>web/src/features/workspace/WorkspaceShell.vue</code> 负责顶部栏、完全收起的侧栏、移动端抽屉和主滚动区。<code>Sidebar.vue</code> 负责模块导航与历史，<code>WorkspaceSettingsMenu.vue</code> 负责账户菜单。<code>WorkspacePreferences.vue</code> 提供模型 API、数据源、通用和用户四个设置页。</p><p><code>web/src/features/settings/</code> 下的 <code>SettingsModels.vue</code>、<code>ConnectionSheet.vue</code>、<code>SettingsSources.vue</code>、<code>SettingsUser.vue</code> 实现连接、数据源和数据管理。模型连接草稿可在不保存的情况下测试；数据源弹窗测试则先调用 <code>saveSource(false)</code> 保存密钥和选项，测试失败或取消弹窗不会回滚。两类弹窗也都提供显式保存操作；默认项选择即时保存。检索草稿选择已保存连接的 ID，全局默认值不替换历史综述自身的模型设置。</p><p><code>web/src/styles/ui.css</code> 负责变量和基础控件，<code>web/src/styles/app.css</code> 负责外壳与浮层。在线版通过共享外壳的账户和历史插槽扩展，不复制外壳。</p>',13)])])}const _=t(o,[["render",s]]);export{l as __pageData,_ as default};
